INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('hash:dda3eca9e160df3c009d08b82237540bb5d32def536be73e219767e7e1d39405', '2026-Q1', 'Mar/2026', '2026-03-25T20:38'::timestamptz, 'Filipe Fernandes Campos', 'filipe fernandes campos', 'PHARUS', 'Carlos Serafim', 8.0, 'Neutro', 9.0, 10.0, 1.0, NULL, 'Sim, em grande parte', 'Sim', NULL, NULL, NULL, 'Ter um plano mais bem estruturado com datas, investimentos, previsao de retorno. Um plano de agenda anual com objetivos de cada agenda enviados com antecedencia. O Cadu eh otimo mas sinto que falta um pouco de gestao do programa como um todo, algo que seja padrao do programa. De pontos positivos, entendimento da minha necessidade pelo Cadu, explicacao clara das estratégias e segurança nas sugestoes.', NULL, 'Ter claro a meta anual e atingi-la. Ter claro as metas e planos de longo prazo, mesmo que eles mudem. Sem plano e meta nao há gestão. Sem gestao nao ha resultado.', 'Esta sendo boa mas vejo potencial para que seja otima.', '2.0', '10/2025', 'nova jornada (backoffice/QV360)', 'NPS_Q1_2026_ENVIADO_MARCO.xlsx', 'pharus 2', NULL, 'aba PHARUS da planilha', 'MARÇO') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquit