INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('hash:1ade6378ff24367e842f803a0fa10076c31a52abba1bf4a3e563b7da41eb7d50', '2026-Q1', 'Mar/2026', '2026-03-26T17:08'::timestamptz, 'Fabio Eduardo Scarabelot', 'fabio eduardo scarabelot', 'PHARUS', 'Tiago Junior', 7.0, 'Neutro', 9.0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Acredito que o trabalho ofertado seja mais valioso para pessoas mais leigas em economia e finanças pessoais, do que para pessoas com maior conhecimento', NULL, 'Resultados concretos financeiros', 'A impressão que tive até o momento, com o devido respeito, é que a contrapartida ofertada pelo valor pago pela consultoria ficou abaixo do esperado. Até o momento, estou aguardando para ver melhoras quanto as oportunidades oferecidas, dentro da idéia de marketing apresentada. Entendi por arriscadas as estratégias até então apresentadas para  implementação, com potencial risco de perdas. Não há disponibilidade de informação estatística ao participante, de forma formatada, sobre determinada estratégia, que permita a este tomar decisões com maior segurança econheciemnto dos riscos envolvidos.', NULL, NULL, 'legado', 'NPS_Q1_2026_ENVIADO_MARCO.xlsx', 'pharus', NULL, 'aba PHARUS da planilha', 'MARÇO') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDE